// bm_debounce.sv: two-flop synchroniser, then a counting debounce. The level
// changes only after the synchronised input has differed from it for CYCLES
// consecutive clocks; a shorter difference restarts the count. rise is a
// one-clock pulse on each 0 -> 1 change of the level.
module bm_debounce #(
    parameter int CYCLES = 1_000_000
) (
    input  logic clk,
    input  logic rst,
    input  logic d_async,
    output logic level,
    output logic rise
);
    localparam int CW = $clog2(CYCLES + 1);
    logic        d;
    logic [CW-1:0] run;

    sync2 u_sync (.clk(clk), .rst(rst), .d(d_async), .q(d));

    always_ff @(posedge clk) begin
        rise <= 1'b0;
        if (rst) begin
            level <= 1'b0;
            run   <= '0;
        end else if (d == level) begin
            run <= '0;
        end else if (run == CW'(CYCLES - 1)) begin
            level <= d;
            run   <= '0;
            rise  <= d;
        end else begin
            run <= run + 1'b1;
        end
    end
endmodule

// press_classifier.sv: debounced BTNC press timing and short/long classification
// for t1_press_classifier, behind the shell's register window.
module press_classifier #(
    parameter int DEBOUNCE_CYCLES = 1_000_000,
    parameter int LONG_CYCLES     = 50_000_000,
    parameter int TICK_CYCLES     = 100_000
) (
    input  logic        clk,
    input  logic        rst,
    input  logic        btn,
    output logic [15:0] led,
    input  logic [6:0]  win_addr,
    input  logic        win_wr,
    input  logic        win_rd,
    input  logic [31:0] win_wdata,
    output logic [31:0] win_rdata
);
    localparam logic [6:0] R_SHORT = 7'h00, R_LONG = 7'h01, R_LAST = 7'h02, R_STATUS = 7'h03;
    localparam int HW = $clog2(LONG_CYCLES + 1);
    localparam int TW = $clog2(TICK_CYCLES + 1);

    logic          lvl, lvl_d, rise, fall;
    logic [HW-1:0] hi;
    logic [TW-1:0] pre;
    logic [15:0]   ticks, short_cnt, long_cnt, last;
    logic          last_long, tog_s, tog_l, is_long;

    bm_debounce #(.CYCLES(DEBOUNCE_CYCLES)) u_db (.clk(clk), .rst(rst), .d_async(btn), .level(lvl), .rise(rise));

    assign fall    = lvl_d && !lvl;
    assign is_long = hi >= HW'(LONG_CYCLES);

    always_ff @(posedge clk) begin
        if (rst) begin
            lvl_d <= 1'b0; hi <= '0; pre <= '0; ticks <= '0;
            short_cnt <= '0; long_cnt <= '0; last <= '0; last_long <= 1'b0;
            tog_s <= 1'b0; tog_l <= 1'b0;
        end else begin
            lvl_d <= lvl;
            if (lvl) begin
                if (hi != HW'(LONG_CYCLES)) hi <= hi + 1'b1;
                if (pre == TW'(TICK_CYCLES - 1)) begin
                    pre <= '0;
                    if (ticks != 16'hFFFF) ticks <= ticks + 1'b1;
                end else begin
                    pre <= pre + 1'b1;
                end
            end else begin
                hi <= '0; pre <= '0; ticks <= '0;
            end
            if (fall) begin
                last      <= ticks;
                last_long <= is_long;
                if (is_long) begin
                    long_cnt <= long_cnt + 1'b1;
                    tog_l    <= ~tog_l;
                end else begin
                    short_cnt <= short_cnt + 1'b1;
                    tog_s     <= ~tog_s;
                end
            end
            if (win_wr && win_addr == R_SHORT) short_cnt <= '0;
            if (win_wr && win_addr == R_LONG)  long_cnt  <= '0;
        end
    end

    assign led = {short_cnt[7:0], 6'd0, tog_l, tog_s};

    always_ff @(posedge clk) begin
        if (rst) win_rdata <= '0;
        else if (win_rd) begin
            case (win_addr)
                R_SHORT:  win_rdata <= {16'd0, short_cnt};
                R_LONG:   win_rdata <= {16'd0, long_cnt};
                R_LAST:   win_rdata <= {15'd0, last_long, last};
                R_STATUS: win_rdata <= {29'd0, tog_l, tog_s, lvl};
                default:  win_rdata <= '0;
            endcase
        end
    end
endmodule

// t1_press_classifier_top.sv: board top (Nexys A7-100T, master-XDC port names).
// Reference design for benchmark task t1_press_classifier; DESIGN_ID "PRSC".
module t1_press_classifier_top #(
    parameter int          CLKS_PER_BIT    = 868,
    parameter int          TIMEOUT_CYCLES  = 100_000,
    parameter int          DEBOUNCE_CYCLES = 1_000_000,
    parameter int          LONG_CYCLES     = 50_000_000,
    parameter int          TICK_CYCLES     = 100_000,
    parameter logic [31:0] BUILD_STAMP     = 32'h0
) (
    input  logic        CLK100MHZ,
    input  logic        CPU_RESETN,
    input  logic        BTNC,
    output logic [15:0] LED,
    input  logic        UART_TXD_IN,
    output logic        UART_RXD_OUT
);
    logic        clk, rst, win_wr, win_rd;
    logic [6:0]  win_addr;
    logic [31:0] win_wdata, win_rdata;

    assign clk = CLK100MHZ;
    reset_sync u_rst (.clk(clk), .rst_n_async(CPU_RESETN), .rst(rst));

    fpga_shell #(.CLKS_PER_BIT(CLKS_PER_BIT), .TIMEOUT_CYCLES(TIMEOUT_CYCLES),
                 .DESIGN_ID(32'h5052_5343), .BUILD_STAMP(BUILD_STAMP)) u_shell (
        .clk(clk), .rst(rst), .uart_rx(UART_TXD_IN), .uart_tx(UART_RXD_OUT),
        .win_addr(win_addr), .win_wr(win_wr), .win_rd(win_rd), .win_wdata(win_wdata), .win_rdata(win_rdata));

    press_classifier #(.DEBOUNCE_CYCLES(DEBOUNCE_CYCLES), .LONG_CYCLES(LONG_CYCLES), .TICK_CYCLES(TICK_CYCLES)) u_pc (
        .clk(clk), .rst(rst), .btn(BTNC), .led(LED),
        .win_addr(win_addr), .win_wr(win_wr), .win_rd(win_rd), .win_wdata(win_wdata), .win_rdata(win_rdata));
endmodule
